<div class="interactive-wrapper"><div class="card shadow-sm border-0 mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#eef2ff"><i class="fas fa-eye text-primary"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Refractive Index Calc</h5><p class="text-muted small mb-0">Calculate angles using Snell's law</p></div></div><button class="btn btn-sm rounded-pill px-3" id="btn-reset" style="background:#f1f5f9;font-weight:600"><i class="fas fa-undo me-1"></i>Reset</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="row g-3"><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">n₁</label><input type="number" id="in-n1" class="form-control form-control-lg" value="1.0" step="0.01"><div class="form-text">Air=1.0</div></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">θ₁ (degrees)</label><input type="number" id="in-t1" class="form-control form-control-lg" value="30" step="0.1"></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">n₂</label><input type="number" id="in-n2" class="form-control form-control-lg" value="1.5" step="0.01"><div class="form-text">Glass=1.5</div></div><div class="col-md-3"><label class="form-label small fw-bold text-secondary text-uppercase mb-2">θ₂ (degrees)</label><input type="number" id="in-t2" class="form-control form-control-lg" value="" placeholder="solve"></div></div><div class="mt-4 text-center"><button class="btn btn-primary btn-lg rounded-pill px-5 shadow-sm" id="btn-calc" style="min-width:260px;max-width:100%"><i class="fas fa-calculator me-2"></i>Calculate</button></div><div class="mt-3 p-3 rounded-4 border" style="background:#f8fafc"><p class="mb-0 small text-muted"><i class="fas fa-info-circle text-primary me-2"></i><b>Snell's Law:</b> n₁ sin(θ₁) = n₂ sin(θ₂)</p></div></div></div><div id="res" class="card shadow-sm border-0 d-none mb-4" style="border-radius:24px;background:#fff;word-break:break-word"><div class="bg-white border-bottom-0 py-4 px-4" style="border-radius:24px 24px 0 0"><div class="d-flex align-items-center justify-content-between flex-wrap gap-2"><div class="d-flex align-items-center"><div style="width:48px;height:48px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.25rem;background:#ecfdf5"><i class="fas fa-check-circle text-success"></i></div><div class="ms-3"><h5 class="mb-0 fw-bold text-dark">Result</h5></div></div><button class="btn btn-success btn-sm rounded-pill px-4 shadow-sm" id="btn-copy"><i class="fas fa-copy me-1"></i>Copy</button></div></div><div class="px-4 pb-4" style="overflow-x:auto"><div class="p-4 rounded-4 bg-light border text-center mb-3"><div class="small fw-bold text-uppercase text-muted mb-1">RESULT</div><div class="display-4 fw-bold text-dark" id="out-main">—</div><div class="small text-muted fw-bold" id="out-unit"></div></div><div id="out-detail" class="row g-3 mb-3"></div><div class="p-4 rounded-4 bg-light border"><h6 class="fw-bold mb-2 small text-uppercase text-muted"><i class="fas fa-lightbulb text-warning me-2"></i>Insights</h6><div id="out-ins" class="small"></div></div></div></div></div><style>.form-control-lg,.form-select-lg{border:1.5px solid #e2e8f0;border-radius:12px;font-size:1.05rem;padding:.75rem 1rem}.form-control:focus,.form-select:focus{border-color:#4f46e5;box-shadow:0 0 0 4px rgba(79,70,229,.1)}</style><script>document.addEventListener("DOMContentLoaded",function(){document.getElementById("btn-calc").addEventListener("click",function(){var n1=parseFloat(document.getElementById("in-n1").value)||1,t1=document.getElementById("in-t1").value,n2=parseFloat(document.getElementById("in-n2").value)||1,t2=document.getElementById("in-t2").value;var result,label;if(!t2||t2===""){var a1=parseFloat(t1)*Math.PI/180;var sinT2=n1*Math.sin(a1)/n2;if(Math.abs(sinT2)>1){document.getElementById("out-main").textContent="Total Internal Reflection";document.getElementById("out-unit").textContent="Critical angle exceeded";document.getElementById("out-ins").innerHTML="<p class=\"text-danger\">sin(θ₂) > 1 — total internal reflection occurs</p>";document.getElementById("res").classList.remove("d-none");return;}result=Math.asin(sinT2)*180/Math.PI;label="θ₂ = "+result.toFixed(2)+"°";}else{var a2=parseFloat(t2)*Math.PI/180;result=Math.asin(n2*Math.sin(a2)/n1)*180/Math.PI;label="θ₁ = "+result.toFixed(2)+"°";}document.getElementById("out-main").textContent=result.toFixed(2)+"°";document.getElementById("out-unit").textContent=label;var crit=Math.asin(Math.min(1,n2>n1?1:n1>n2?n2/n1:1))*180/Math.PI;document.getElementById("out-detail").innerHTML='<div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">n₁</div><div class="h5 fw-bold mb-0 text-primary">'+n1+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">n₂</div><div class="h5 fw-bold mb-0 text-info">'+n2+'</div></div></div><div class="col-4"><div class="p-3 rounded-4 bg-light border text-center"><div class="small fw-bold text-uppercase text-muted mb-1">Critical Angle</div><div class="h5 fw-bold mb-0 text-warning">'+(n1>n2?crit.toFixed(2)+"°":"N/A")+'</div></div></div>';document.getElementById("out-ins").innerHTML="<p>"+label+" via Snell's Law</p>";document.getElementById("res").classList.remove("d-none");});document.getElementById("btn-reset").addEventListener("click",function(){document.getElementById("in-n1").value=1;document.getElementById("in-t1").value=30;document.getElementById("in-n2").value=1.5;document.getElementById("in-t2").value="";document.getElementById("res").classList.add("d-none");});document.getElementById("btn-copy").addEventListener("click",function(){navigator.clipboard.writeText(document.getElementById("out-main").textContent);var b=this;b.innerHTML="Copied!";setTimeout(function(){b.innerHTML="<i class=\"fas fa-copy me-1\"></i>Copy";},2e3);});});</script>